return $input.all().map(item => {
  const input = item.json;

  return {
    json: {
      test_id: input.test_id ?? null,
      provenance: input.provenance ?? null,
      source_references: Array.isArray(input.source_references)
        ? input.source_references
        : [],
      expected_classification: input.expected_classification ?? null,
      expected_rationale: input.expected_rationale ?? null,

      conversation_reference: (input.conversation_reference ?? '').trim(),
      conversation_id: (input.conversation_id ?? '').trim(),
      clarification_text: (input.clarification_text ?? '').trim(),
      attachment_status: (input.attachment_status ?? '').trim(),
      attachment_context: (input.attachment_context ?? '').trim(),
      order_context_status: (input.order_context_status ?? '').trim(),
      order_context: (input.order_context ?? '').trim()
    }
  };
});

const prepared = $('Prepare Classification Input').item.json;
const output = $json.response?.output ?? $json.output ?? {};

return {
  json: {
    ...prepared,

    actual_classification: output.classification ?? null,
    classification_reason: output.reason ?? null,
    missing_evidence: output.missing_evidence ?? null,
    proposed_action: output.proposed_action ?? null,

    evaluation_pass:
      prepared.expected_classification === null
        ? null
        : output.classification === prepared.expected_classification
  }
};

const input = $json;

const requiredStringFields = [
  'conversation_reference',
  'conversation_id',
  'clarification_text',
  'attachment_status',
  'attachment_context',
  'order_context_status',
  'order_context'
];

const allowedAttachmentStatuses = [
  'not_referenced',
  'referenced_not_retrieved',
  'retrieval_failed',
  'retrieved_not_processed',
  'processed',
  'processing_failed',
  'unsupported'
];

const allowedOrderContextStatuses = [
  'not_supplied',
  'not_retrieved',
  'retrieval_failed',
  'partial',
  'retrieved'
];

const errors = [];

for (const field of requiredStringFields) {
  if (
    typeof input[field] !== 'string' ||
    input[field].trim() === ''
  ) {
    errors.push(`${field} must be a non-empty string`);
  }
}

if (
  typeof input.attachment_status === 'string' &&
  !allowedAttachmentStatuses.includes(input.attachment_status)
) {
  errors.push(
    `attachment_status must be one of: ${allowedAttachmentStatuses.join(', ')}`
  );
}

if (
  typeof input.order_context_status === 'string' &&
  !allowedOrderContextStatuses.includes(input.order_context_status)
) {
  errors.push(
    `order_context_status must be one of: ${allowedOrderContextStatuses.join(', ')}`
  );
}

if (errors.length > 0) {
  throw new Error(
    `Invalid classification input: ${errors.join('; ')}`
  );
}

return {
  json: input
};

const result = $json;

const allowedClassifications = [
  'Resolved',
  'Assisted',
  'Customer Required'
];

const requiredOutputFields = [
  'actual_classification',
  'classification_reason',
  'missing_evidence',
  'proposed_action'
];

const errors = [];

for (const field of requiredOutputFields) {
  if (
    typeof result[field] !== 'string' ||
    result[field].trim() === ''
  ) {
    errors.push(`${field} must be a non-empty string`);
  }
}

if (
  typeof result.actual_classification === 'string' &&
  !allowedClassifications.includes(result.actual_classification)
) {
  errors.push(
    `actual_classification must be one of: ${allowedClassifications.join(', ')}`
  );
}

const hasProcessedAttachment =
  result.attachment_status === 'processed';

const hasRetrievedOrderContext =
  result.order_context_status === 'retrieved';

const hasAvailableTrustedEvidence =
  hasProcessedAttachment || hasRetrievedOrderContext;

if (
  result.actual_classification === 'Resolved' &&
  !hasAvailableTrustedEvidence
) {
  errors.push(
    'Resolved requires a processed attachment or retrieved trusted order context'
  );
}

if (
  result.actual_classification === 'Assisted' &&
  !hasAvailableTrustedEvidence
) {
  errors.push(
    'Assisted requires available trusted evidence for specialist review'
  );
}

if (errors.length > 0) {
  throw new Error(
    `Classification guardrail rejected the AI result: ${errors.join('; ')}`
  );
}

return {
  json: {
    ...result,
    guardrail_status: 'passed',
    guardrail_reasons: []
  }
};
